"""Immediate public construction round trip and explicit daily-service cache classification."""
import hashlib,json
from playwright.sync_api import sync_playwright
from test_mobile_rendering import ROOT,html
source=(ROOT/'assets/game.js').read_text()
probe=r'''
const continuationCanonical=v=>Array.isArray(v)?v.map(continuationCanonical):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,continuationCanonical(v[k])])):v;
function continuationDiff(a,b,path=''){if(typeof a!==typeof b||a===null||b===null)return a===b?[]:[path];if(typeof a!=='object')return a===b?[]:[path];const keys=new Set([...Object.keys(a),...Object.keys(b)]);return [...keys].flatMap(k=>!(k in a)||!(k in b)?[path+'.'+k]:continuationDiff(a[k],b[k],path+'.'+k));}
window.__continuation={fresh:(kind='farm-home')=>{__townTest.reset('settlement',42);paused=true;G.autoBuild=false;const parcel=ANNEX_PARCELS.find(p=>p.id==='east-meadow');purchaseParcel(parcel.id,parcelSurvey(parcel).price);for(let x=43;x<=63;x++)construct('road',x,15,true);for(let x=69;x<=76;x++)construct('road',x,15,true);flushRoadBatch();if(kind==='farm-home'){construct('farm',72,16,true);construct('home',70,16,true);}else if(kind==='transit'){const p=buildableCandidates('business').find(p=>canPlace(p.x,p.y,true,'transit_depot'));construct('transit_depot',p.x,p.y,true);}else{G.roadWear[roadId(63,15)]=40;construct('repair',63,15,true);}const raw=archivePayload(),before=JSON.parse(raw),cash=totalMoney(),rng=rngState;if(!hydrateSave(raw))throw Error('Fresh construction archive rejected');const after=JSON.parse(archivePayload());return {kind,differences:continuationDiff(continuationCanonical(before),continuationCanonical(after)),moneyUnchanged:cash===totalMoney(),rngUnchanged:rng===rngState,buildingIdentities:before.buildings.length===after.buildings.length,households:before.households.length,farms:before.firms.filter(f=>f.kind==='farm').length};},
 defaults:()=>{window.__continuation.fresh();G.stats.marketConfidence=0;G.households.at(-1).creditScore=0;G.firms.at(-1).creditScore=0;G.firms.at(-1).salesTrend=0;const zero=archivePayload();if(!hydrateSave(zero)||G.stats.marketConfidence!==0||G.households.at(-1).creditScore!==0||G.firms.at(-1).creditScore!==0||G.firms.at(-1).salesTrend!==0)throw Error('Valid zero was defaulted away');window.__continuation.fresh();const expected=continuationCanonical(JSON.parse(archivePayload())),legacy=JSON.parse(archivePayload()),f=legacy.firms.at(-1),h=legacy.households.at(-1),b=legacy.buildings.find(b=>b.id===f.building);legacy.schema=5;for(const k of ['ask','operating','salesTrend','revenueTrend','marginTrend','scale','workingCapitalRaised','unitCost','creditScore','lossDays'])delete f[k];delete h.deposits;delete h.creditScore;delete b.baseValue;delete b.title;const caller=JSON.stringify(legacy);if(!hydrateSave(legacy)||caller!==JSON.stringify(legacy))throw Error('Legacy defaults/caller independence failed');return {validZerosPreserved:true,legacyDifferences:continuationDiff(expected,continuationCanonical(JSON.parse(archivePayload()))),callerUnchanged:true};},
 aged:(scenario,days)=>{__townTest.reset(scenario,42);paused=true;__townTest.step(days);const raw=archivePayload(),before=JSON.parse(raw),money=totalMoney(),rng=rngState;const model=()=>{const g=JSON.parse(archivePayload());return continuationCanonical(g)};__townTest.step(45);const expected=model();if(!hydrateSave(raw))throw Error('Committed archive rejected');const loaded=JSON.parse(archivePayload()),differences=continuationDiff(continuationCanonical(before),continuationCanonical(loaded));const moneyUnchanged=money===totalMoney(),rngUnchanged=rng===rngState;__townTest.step(45);const actual=model();return {scenario,days,differences,moneyUnchanged,rngUnchanged,replayDifferences:continuationDiff(expected,actual),privateMemberships:before.privateServiceProvision?.fireMembers||0,publicPaid:before.serviceProvision?.health?.paid??null};}
};'''
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click();fresh=[p.evaluate('kind=>__continuation.fresh(kind)',kind) for kind in ['farm-home','transit','repair']];defaults=p.evaluate('__continuation.defaults()');aged=[p.evaluate('a=>__continuation.aged(...a)',[scenario,days]) for scenario,days in [('settlement',180),('industrial',360)]];b.close()
result={'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'freshPublicConstruction':fresh,'validZeroAndLegacyDefaults':defaults,'committedServiceStates':aged};print(json.dumps(result,indent=2),flush=True)
assert all(not row['differences'] and row['moneyUnchanged'] and row['rngUnchanged'] for row in fresh),fresh
assert not defaults['legacyDifferences'],defaults
for row in aged:
 assert row['moneyUnchanged'] and row['rngUnchanged'] and not row['replayDifferences'],row
 assert not row['differences'],row
print('PASS fresh complete-state construction equality; validated paid service receipts preserved; 45-day complete-state replay with no excluded fields')
